const ACTOR_ID='uyfjMbPtsvmRBL4EL';
const BUSINESS_TAB='Pracuj Jobs',HISTORY_TAB='Pracuj Companies',RUN_TAB='Pracuj Runs',LOCK_TAB='_PRACUJ_WORKFLOW_LOCK';
const MAX_EXISTING=5000,MAX_DATASET=1000;
const BUSINESS_HEADERS=['jobKey','jobId','title','companyName','companyKey','companyProfileUrl','sourceUrl','locations','salaryText','workModes','contractTypes','publishedAt','expiresAt','firstSeenAt','lastSeenAt','firstSeenRunId','lastRunId','firstObservationType','searchScope'];
const HISTORY_HEADERS=['signalKey','runId','companyKey','companyName','companyProfileUrl','baselineJobs','newlyObservedJobs','observedJobs','observedAt','keyword','location'];
const RUN_HEADERS=['runId','status','keyword','location','maxItems','startedAt','finishedAt','datasetId','rowsRead','rowsRejected','baselineJobs','newlyObservedJobs','rowsUpdated','companiesObserved','maxChargeUsd','buildNumber','executionId','notes'];
function searchInput(input){
 const keyword=String(input?.keyword??'').trim(),location=String(input?.location??'').trim();
 if(!keyword||keyword.length>100||location.length>100)throw new Error('Set a keyword (1–100 characters) and optionally a Polish location (up to 100 characters).');
 const maxItems=Number(input.maxItems);if(!Number.isInteger(maxItems)||maxItems<1||maxItems>100)throw new Error('maxItems must be an integer from 1 to 100.');
 if(input.scrapeJobDetails===true||input.startUrls?.length)throw new Error('This template supports keyword/location listing runs only, with details disabled and no startUrls.');
 return {keyword,location,maxItems,scrapeJobDetails:false};
}
function scope(input){return JSON.stringify([input.keyword,input.location]);}
function config(input){
 const c={...input,...searchInput(input)};c.spreadsheetId=String(input.spreadsheetId??'').trim();c.resumeRunId=String(input.resumeRunId??'').trim();c.maxChargeUsd=Number(input.maxChargeUsd);
 if(!/^[A-Za-z0-9_-]{20,100}$/.test(c.spreadsheetId))throw new Error('Paste the spreadsheet ID (not its URL) in Configure search before starting a paid run.');
 if(c.resumeRunId&&!/^[A-Za-z0-9]{17}$/.test(c.resumeRunId))throw new Error('resumeRunId must be the 17-character Apify run ID.');
 if(!Number.isFinite(c.maxChargeUsd)||c.maxChargeUsd<0.01||c.maxChargeUsd>1)throw new Error('maxChargeUsd must be between 0.01 and 1 USD.');return c;
}
function originalInput(input){return searchInput(input);}
function checkScope(input,ledger){for(const r of ledger){if(r[2]!==input.keyword||String(r[3]??'')!==input.location)throw new Error('This destination belongs to another keyword/location. Use a new spreadsheet for a different search to keep baseline semantics reliable.');}}
function prepareSheet(meta){
 if(!Array.isArray(meta.sheets))throw new Error('Cannot read destination tabs.');const names=meta.sheets.map(s=>s.properties.title);
 if(names.includes(LOCK_TAB))throw new Error('Pracuj destination is locked. Check active executions and Pracuj Runs. Only after none is active, remove _PRACUJ_WORKFLOW_LOCK and resume the saved run ID.');
 const requests=[{addSheet:{properties:{title:LOCK_TAB,gridProperties:{rowCount:5,columnCount:2}}}}];
 for(const title of [BUSINESS_TAB,HISTORY_TAB,RUN_TAB])if(!names.includes(title))requests.push({addSheet:{properties:{title,gridProperties:{rowCount:MAX_EXISTING+2,columnCount:22}}}});return {requests};
}
function validateTable(values,headers,label){
 if(!values?.length)return [];if(headers.some((h,i)=>values[0]?.[i]!==h))throw new Error(label+' headers do not match the managed schema.');
 const rows=values.slice(1);if(rows.length>MAX_EXISTING)throw new Error(label+' exceeds 5000 rows. Archive to a new destination.');const keys=new Set();for(const r of rows){if(!r[0]||keys.has(String(r[0])))throw new Error(label+' contains missing or duplicate keys.');keys.add(String(r[0]));}return rows;
}
function checkRun(run){
 if(run.actId!==ACTOR_ID)throw new Error('Recovery run belongs to another Actor.');if(['FAILED','ABORTED','TIMED-OUT'].includes(run.status))throw new Error('Pracuj run '+run.id+' ended '+run.status+'. Partial output will not be imported.');
 if(!['READY','RUNNING','TIMING-OUT','ABORTING','SUCCEEDED'].includes(run.status))throw new Error('Unsupported Actor status: '+run.status);return run.status==='SUCCEEDED';
}
function checkDataset(meta){
 if(!Number.isInteger(meta.itemCount)||meta.itemCount<0||meta.itemCount>MAX_DATASET)throw new Error('Invalid or oversized dataset. The 1000-row bound never silently truncates results.');
 // An empty output is not sufficient evidence of a successful empty search.
 if(meta.itemCount===0)throw new Error('Pracuj returned no rows. Inspect the Actor log before interpreting this as no matching jobs. Existing jobs and company observations are unchanged.');return meta.itemCount;
}
const scalar=v=>typeof v==='string'?v.trim().slice(0,2000):'';
const list=v=>Array.isArray(v)?v.filter(x=>typeof x==='string').map(scalar).join('; '):scalar(v);
const date=v=>typeof v==='string'&&Number.isFinite(Date.parse(v))?v:'';
function normalize(item){
 if(!item||!scalar(item.title)||typeof item.url!=='string')return null;
 const m=item.url.match(/^https:\/\/(?:www\.)?pracuj\.pl\/praca\/[^?#\s]+,oferta,(\d{5,20})(?:[?#]|$)/i);if(!m)return null;
 const id=m[1],name=scalar(item.company?.name),cid=item.company?.id;
 const validId=(typeof cid==='number'&&Number.isSafeInteger(cid)&&cid>0)||(typeof cid==='string'&&/^\d+$/.test(cid));
 // Source IDs group employers; fallback names are exact labels, not verified entities.
 const companyKey=validId?'id:'+cid:name?'name:'+name:'unknown-job:'+id;
 const profile=validId?'https://pracodawcy.pracuj.pl/company/'+cid:'';
 return {key:'pracuj:'+id,id,title:scalar(item.title),name,companyKey,profile,url:item.url.split(/[?#]/)[0],locations:list(item.locations),salary:scalar(item.salary),modes:list(item.workModes),contracts:list(item.typesOfContract),published:date(item.publishedAt),expires:date(item.expiresAt)};
}
function ledgerRow(ctx,status,counts={},notes=''){
 const {run,input,executionId}=ctx;return [run.id,status,input.keyword,input.location,input.maxItems,run.startedAt,run.finishedAt??'',run.defaultDatasetId,counts.read??'',counts.rejected??'',counts.baselines??'',counts.newJobs??'',counts.updated??'',counts.companies??'',run.options?.maxTotalChargeUsd??'',run.buildNumber??'',String(executionId),notes];
}
function planWrites(ctx,items,existing,ledger,datasetCount,signals=[]){
 if(!Array.isArray(items)||items.length!==datasetCount)throw new Error('Dataset retrieval is incomplete.');checkDataset({itemCount:items.length});const input=originalInput(ctx.input);checkScope(input,ledger);
 const time=ctx.run.finishedAt;if(!time||!Number.isFinite(Date.parse(time)))throw new Error('Completed run timestamp missing.');
 const oldMap=new Map(existing.map((r,i)=>[r[0],{row:r,index:i+2}]));
 for(const r of existing){if(r[18]!==scope(input))throw new Error('Existing job search scope differs from this run.');if(!Number.isFinite(Date.parse(r[14])))throw new Error('Invalid lastSeenAt.');if(Date.parse(r[14])>Date.parse(time))throw new Error('This run predates existing observations. Use a separate spreadsheet for older runs.');}
 const known=ledger.findIndex(r=>r[0]===ctx.run.id),replayed=known>=0&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(ledger[known][1]);
 const baseline=!ledger.some(r=>r[0]!==ctx.run.id&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(r[1]));
 const unique=new Map(),counts={read:items.length,rejected:0,duplicates:0,baselines:0,newJobs:0,updated:0,replayed:0,companies:0};
 for(const item of items){const n=normalize(item);if(!n){counts.rejected++;continue;}if(unique.has(n.key)){counts.duplicates++;continue;}unique.set(n.key,n);}
 if(!unique.size)throw new Error('No valid Pracuj job identities. Possible schema drift; no jobs or signals written.');
 const data=[{range:`'${BUSINESS_TAB}'!A1:S1`,values:[BUSINESS_HEADERS]},{range:`'${HISTORY_TAB}'!A1:K1`,values:[HISTORY_HEADERS]},{range:`'${RUN_TAB}'!A1:R1`,values:[RUN_HEADERS]}];
 const companies=new Map();let next=existing.length+2;
 for(const n of unique.values()){
  const old=oldMap.get(n.key),r=old?.row;
  if(replayed){if(!r||r[16]!==ctx.run.id)throw new Error('Successful run ledger disagrees with job state. Restore the destination before replay.');counts.replayed++;continue;}
  if(r?.[16]===ctx.run.id)throw new Error('Jobs contain this run without a successful ledger. Inspect interrupted writes before recovery.');
  if(r&&Date.parse(r[14])===Date.parse(time))throw new Error('Different runs have identical observation timestamps. Review before import.');
  const type=r?r[17]:baseline?'BASELINE':'NEW';const row=old?.index??next++;if(row>MAX_EXISTING+1)throw new Error('Jobs table is full.');
  data.push({range:`'${BUSINESS_TAB}'!A${row}:S${row}`,values:[[n.key,n.id,n.title,n.name,n.companyKey,n.profile,n.url,n.locations,n.salary,n.modes,n.contracts,n.published,n.expires,r?.[13]||time,time,r?.[15]||ctx.run.id,ctx.run.id,type,scope(input)]]});
  if(!r){if(baseline)counts.baselines++;else counts.newJobs++;}else counts.updated++;
  let c=companies.get(n.companyKey);if(!c){c={n,baseline:0,newJobs:0,observed:0};companies.set(n.companyKey,c);}c.observed++;if(!r){if(baseline)c.baseline++;else c.newJobs++;}
 }
 const signalMap=new Map(signals.map((r,i)=>[r[0],{row:r,index:i+2}]));let snext=signals.length+2;
 for(const [key,c]of companies){const sk=ctx.run.id+':'+key;if(signalMap.has(sk))throw new Error('Company signals contain this run without a successful ledger. Inspect interrupted writes.');if(snext>MAX_EXISTING+1)throw new Error('Company signals are full.');data.push({range:`'${HISTORY_TAB}'!A${snext}:K${snext}`,values:[[sk,ctx.run.id,key,c.n.name,c.n.profile,c.baseline,c.newJobs,c.observed,time,input.keyword,input.location]]});snext++;}
 if(replayed){for(const n of unique.values())if(!signalMap.has(ctx.run.id+':'+n.companyKey))throw new Error('Replay is missing company signal rows. Restore the destination.');}
 counts.companies=companies.size;
 const status=counts.rejected?'PARTIAL_ROWS_REJECTED':'IMPORTED';const notes=`${counts.baselines} baseline jobs; ${counts.newJobs} newly observed jobs; ${counts.updated} refreshed; ${counts.replayed} replayed. First seen is not publication time. Missing jobs are not assumed closed. Company counts describe this bounded search only.`;
 const ri=known>=0?known+2:ledger.length+2;if(ri>MAX_EXISTING+1)throw new Error('Run log is full.');if(!replayed)data.push({range:`'${RUN_TAB}'!A${ri}:R${ri}`,values:[ledgerRow(ctx,status,counts,notes)]});
 return {body:{valueInputOption:'RAW',data},summary:{status,runId:ctx.run.id,datasetId:ctx.run.defaultDatasetId,...counts,notes}};
}

return [{json:config($json)}];

