function ledgerRow(ctx,status,counts={},notes=''){
 const {run,input,executionId}=ctx;return [run.id,status,input.keyword,input.location,input.maxItems,run.startedAt,run.finishedAt??'',run.defaultDatasetId,counts.read??'',counts.rejected??'',counts.baselines??'',counts.newJobs??'',counts.updated??'',counts.companies??'',run.options?.maxTotalChargeUsd??'',run.buildNumber??'',String(executionId),notes];
}
function planWrites(ctx,items,existing,ledger,datasetCount,signals=[]){
 if(!Array.isArray(items)||items.length!==datasetCount)throw new Error('Dataset retrieval is incomplete.');checkDataset({itemCount:items.length});const input=originalInput(ctx.input);checkScope(input,ledger);
 const time=ctx.run.finishedAt;if(!time||!Number.isFinite(Date.parse(time)))throw new Error('Completed run timestamp missing.');
 const oldMap=new Map(existing.map((r,i)=>[r[0],{row:r,index:i+2}]));
 for(const r of existing){if(r[18]!==scope(input))throw new Error('Existing job search scope differs from this run.');if(!Number.isFinite(Date.parse(r[14])))throw new Error('Invalid lastSeenAt.');if(Date.parse(r[14])>Date.parse(time))throw new Error('This run predates existing observations. Use a separate spreadsheet for older runs.');}
 const known=ledger.findIndex(r=>r[0]===ctx.run.id),replayed=known>=0&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(ledger[known][1]);
 const baseline=!ledger.some(r=>r[0]!==ctx.run.id&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(r[1]));
 const unique=new Map(),counts={read:items.length,rejected:0,duplicates:0,baselines:0,newJobs:0,updated:0,replayed:0,companies:0};
 for(const item of items){const n=normalize(item);if(!n){counts.rejected++;continue;}if(unique.has(n.key)){counts.duplicates++;continue;}unique.set(n.key,n);}
 if(!unique.size)throw new Error('No valid Pracuj job identities. Possible schema drift; no jobs or signals written.');
 const data=[{range:`'${BUSINESS_TAB}'!A1:S1`,values:[BUSINESS_HEADERS]},{range:`'${HISTORY_TAB}'!A1:K1`,values:[HISTORY_HEADERS]},{range:`'${RUN_TAB}'!A1:R1`,values:[RUN_HEADERS]}];
 const companies=new Map();let next=existing.length+2;
 for(const n of unique.values()){
  const old=oldMap.get(n.key),r=old?.row;
  if(replayed){if(!r||r[16]!==ctx.run.id)throw new Error('Successful run ledger disagrees with job state. Restore the destination before replay.');counts.replayed++;continue;}
  if(r?.[16]===ctx.run.id)throw new Error('Jobs contain this run without a successful ledger. Inspect interrupted writes before recovery.');
  if(r&&Date.parse(r[14])===Date.parse(time))throw new Error('Different runs have identical observation timestamps. Review before import.');
  const type=r?r[17]:baseline?'BASELINE':'NEW';const row=old?.index??next++;if(row>MAX_EXISTING+1)throw new Error('Jobs table is full.');
  data.push({range:`'${BUSINESS_TAB}'!A${row}:S${row}`,values:[[n.key,n.id,n.title,n.name,n.companyKey,n.profile,n.url,n.locations,n.salary,n.modes,n.contracts,n.published,n.expires,r?.[13]||time,time,r?.[15]||ctx.run.id,ctx.run.id,type,scope(input)]]});
  if(!r){if(baseline)counts.baselines++;else counts.newJobs++;}else counts.updated++;
  let c=companies.get(n.companyKey);if(!c){c={n,baseline:0,newJobs:0,observed:0};companies.set(n.companyKey,c);}c.observed++;if(!r){if(baseline)c.baseline++;else c.newJobs++;}
 }
 const signalMap=new Map(signals.map((r,i)=>[r[0],{row:r,index:i+2}]));let snext=signals.length+2;
 for(const [key,c]of companies){const sk=ctx.run.id+':'+key;if(signalMap.has(sk))throw new Error('Company signals contain this run without a successful ledger. Inspect interrupted writes.');if(snext>MAX_EXISTING+1)throw new Error('Company signals are full.');data.push({range:`'${HISTORY_TAB}'!A${snext}:K${snext}`,values:[[sk,ctx.run.id,key,c.n.name,c.n.profile,c.baseline,c.newJobs,c.observed,time,input.keyword,input.location]]});snext++;}
 if(replayed){for(const n of unique.values())if(!signalMap.has(ctx.run.id+':'+n.companyKey))throw new Error('Replay is missing company signal rows. Restore the destination.');}
 counts.companies=companies.size;
 const status=counts.rejected?'PARTIAL_ROWS_REJECTED':'IMPORTED';const notes=`${counts.baselines} baseline jobs; ${counts.newJobs} newly observed jobs; ${counts.updated} refreshed; ${counts.replayed} replayed. First seen is not publication time. Missing jobs are not assumed closed. Company counts describe this bounded search only.`;
 const ri=known>=0?known+2:ledger.length+2;if(ri>MAX_EXISTING+1)throw new Error('Run log is full.');if(!replayed)data.push({range:`'${RUN_TAB}'!A${ri}:R${ri}`,values:[ledgerRow(ctx,status,counts,notes)]});
 return {body:{valueInputOption:'RAW',data},summary:{status,runId:ctx.run.id,datasetId:ctx.run.defaultDatasetId,...counts,notes}};
}

const ranges=$json.body.valueRanges;
