  data.push({range:`'${BUSINESS_TAB}'!A${row}:S${row}`,values:[[n.key,n.id,n.title,n.name,n.companyKey,n.profile,n.url,n.locations,n.salary,n.modes,n.contracts,n.published,n.expires,r?.[13]||time,time,r?.[15]||ctx.run.id,ctx.run.id,type,scope(input)]]});
  if(!r){if(baseline)counts.baselines++;else counts.newJobs++;}else counts.updated++;
