 const ri=known>=0?known+2:ledger.length+2;if(ri>MAX_EXISTING+1)throw new Error('Run log is full.');if(!replayed)data.push({range:`'${RUN_TAB}'!A${ri}:R${ri}`,values:[ledgerRow(ctx,status,counts,notes)]});
 return {body:{valueInputOption:'RAW',data},summary:{status,runId:ctx.run.id,datasetId:ctx.run.defaultDatasetId,...counts,notes}};
}

